package org.olcbox.app.ui

import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.Box
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.layout.ContentScale
import org.olcbox.app.data.reed.decodeImageBitmap

// Логотип Reed зашит в код как PNG-байты (base64) и декодируется через
// проверенный decodeImageBitmap (тот же путь, что у аватарок). Намеренно НЕ
// используем compose-resources/painterResource на этом экране: на Android это
// был первый ресурс такого типа и он валил приложение при запуске. Байтовый
// путь не зависит от системы ресурсов и не бросает исключений (null при сбое).
private val reedLogoBitmap: ImageBitmap? by lazy {
    try {
        decodeImageBitmap(decodeBase64(REED_LOGO_PNG_BASE64))
    } catch (e: Throwable) {
        null
    }
}

@Composable
fun ReedBrandLogo(modifier: Modifier = Modifier, contentDescription: String? = "Reed VPN") {
    val bitmap = remember { reedLogoBitmap }
    if (bitmap != null) {
        Image(
            bitmap = bitmap,
            contentDescription = contentDescription,
            contentScale = ContentScale.Fit,
            modifier = modifier,
        )
    } else {
        // Безопасный фолбэк: пустой бокс того же размера, без краша.
        Box(modifier = modifier)
    }
}

// Самописный декодер base64 — чтобы не зависеть от версии stdlib/opt-in API.
private const val B64_ALPHABET =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

private fun decodeBase64(input: String): ByteArray {
    val table = IntArray(128) { -1 }
    for (i in B64_ALPHABET.indices) table[B64_ALPHABET[i].code] = i
    val out = ArrayList<Byte>(input.length * 3 / 4)
    var buffer = 0
    var bits = 0
    for (c in input) {
        if (c == '=' || c == '\n' || c == '\r' || c == ' ') continue
        val v = if (c.code < 128) table[c.code] else -1
        if (v < 0) continue
        buffer = (buffer shl 6) or v
        bits += 6
        if (bits >= 8) {
            bits -= 8
            out.add(((buffer shr bits) and 0xFF).toByte())
        }
    }
    return out.toByteArray()
}

private const val REED_LOGO_PNG_BASE64 =
    ""
